    'admin_leader_operating_system.leader.opportunity_modal_empty' => 'Il n’y a pas d’autres signaux pour le moment, mais il faut continuer à se concentrer sur des appels à l’action plus efficaces, une meilleure conversion et un parcours plus simple vers l’inscription ou l’achat.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.label' => 'Augmenter la part des clics dirigés vers la boutique en ligne ou les offres de réduction',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.text' => 'Le collaborateur totalise %s clics, mais seulement %s%% d’entre eux aboutissent à la boutique en ligne Forever ou à des pages de réductions.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Place plus haut sur la page l’appel à l’action vers la boutique en ligne ou la remise, puis répète-le près du bas du profil ou de l’article de blog.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Ajoute un appel à l’action plus clair sur le principal parcours de navigation afin que les visiteurs accèdent à une destination Forever plutôt qu’à du contenu uniquement informatif.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'Pour la source %s, teste un appel à l’action plus clair qui redirige directement les utilisateurs du contenu vers la boutique en ligne Forever ou vers la page de réductions.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Vérifie si les blocs du blog, des ventes et des remises rendent le parcours d\'achat suffisamment visible et récurrent.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.label' => 'Transformer les clics sur la boutique en ligne en inscriptions ou en achats',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.text' => 'Le collaborateur a déjà %s clics sur la boutique en ligne, mais aucune inscription pour cette période.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_1' => 'Vérifie que le clic ouvre la bonne URL de parrainage et mène à la page prévue ou à l’écran de la boutique en ligne, sans erreur.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_2' => 'Améliore le message avant le clic : explique ce que le visiteur va obtenir, pourquoi cliquer maintenant et ce qui se passe après avoir ouvert la page Forever.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Teste un parcours plus simple vers l’inscription ou l’achat et supprime les étapes qui prêtent à confusion après le premier clic.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Si la plupart des visites proviennent de %s, vérifie que la destination est correctement localisée et qu’elle ouvre la bonne version pour le marché.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.label' => 'Augmenter le taux de conversion pendant que le trafic progresse',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.text' => 'Le trafic augmente de %s%%, mais le taux d’inscription n’est que de %s%%. Les clics supplémentaires ne génèrent donc pas encore assez de résultats.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Garde la source qui génère de la croissance, mais améliore le texte du CTA et le message d’introduction afin de mieux cerner l’intention d’achat des prospects.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'Renforce la confiance avant l’appel à l’action avec un témoignage, un résultat, une mini FAQ ou une explication claire de ce qui se passe après le clic.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Compare les sources de clics et continue de privilégier uniquement les canaux qui génèrent des inscriptions ou des prospects de meilleure qualité, et pas seulement du trafic.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Mets à profit l’intérêt existant pour créer un parcours de vente plus solide',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.text' => 'L’application génère déjà des signaux par WhatsApp (%1$s), grâce aux produits (%2$s) et aux inscriptions (%3$s), mais cela ne conduit toujours pas assez de personnes à la boutique.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_1' => 'Place une entrée principale claire vers la boutique au-dessus des autres options de vente.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_2' => 'Harmonise le message dans le contenu, sur WhatsApp et dans les blocs de vente afin qu’ils indiquent tous la même prochaine étape.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_3' => 'Conserve les blocs qui suscitent de l’intérêt, mais indique clairement où cliquer pour acheter ou s’inscrire immédiatement.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.label' => 'Entretiens ton élan grâce à de petites optimisations',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.text' => 'Le potentiel de croissance n’est pas élevé à cause d’un problème majeur, mais grâce à de petites possibilités d’amélioration.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_1' => 'Continue à diriger le trafic vers les points d’appel à l’action les plus performants.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_2' => 'Continue à tester le texte du titre, l’ordre des appels à l’action et les éléments de confiance pour maintenir ou réduire le score d’opportunité.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_3' => 'Continue à vérifier si les clics supplémentaires se traduisent par des inscriptions, et pas seulement par une hausse du trafic.',
